const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function text(value) {
  return String(value ?? '').trim();
}

function key(value) {
  return text(value).toLowerCase().replace(/[^a-z0-9]/g, '');
}

function read(row, ...names) {
  const entries = Object.entries(row || {});
  const wanted = names.map(key);
  for (const name of wanted) {
    const match = entries.find(([column, value]) => key(column) === name && value !== null && value !== undefined);
    if (match) return match[1];
  }
  return '';
}

function directCount(row, ...names) {
  const raw = text(read(row, ...names));
  if (!raw) return null;
  const value = Number(raw.replace(/[,\s]/g, ''));
  return Number.isFinite(value) ? Math.max(0, Math.trunc(value)) : null;
}

function emailFrom(row) {
  const named = text(read(row, 'Email', 'Contributor Email', 'Worker Email', 'Candidate Email')).toLowerCase();
  if (EMAIL_RE.test(named)) return named;
  for (const value of Object.values(row || {})) {
    const candidate = text(value).toLowerCase();
    if (EMAIL_RE.test(candidate)) return candidate;
  }
  return '';
}

function classify(value) {
  const status = text(value).toLowerCase();
  if (/accept|approve|complete|pass/.test(status)) return 'accepted';
  if (/reject|fail|invalid/.test(status)) return 'rejected';
  if (/rework|revision|fixable|needs.?fix/.test(status)) return 'rework';
  if (/review|pending|queue|hold/.test(status)) return 'evaluation_pending';
  return 'submitted';
}

const byEmail = new Map();
const asOf = new Date().toISOString().slice(0, 10);

for (const item of items) {
  const row = item.json;
  const email = emailFrom(row);
  if (!EMAIL_RE.test(email)) continue;

  const direct = {
    submitted: directCount(row, 'Submitted', 'Total Submitted', 'Task Count', 'Task Count All Time'),
    accepted: directCount(row, 'Accepted', 'Total Accepted'),
    rejected: directCount(row, 'Rejected', 'Total Rejected'),
    rework: directCount(row, 'Rework', 'Needs Revision', 'Requiring Rework'),
    evaluation_pending: directCount(row, 'Evaluation Pending', 'To Be Reviewed', 'Pending'),
  };

  if (Object.values(direct).some((value) => value !== null)) {
    byEmail.set(email, {
      p_email: email,
      p_project_slug: 'sentinel_ultra',
      p_as_of: asOf,
      p_submitted: direct.submitted,
      p_accepted: direct.accepted,
      p_rejected: direct.rejected,
      p_rework: direct.rework,
      p_evaluation_pending: direct.evaluation_pending,
      p_source_sheet: 'Snorkel MainSentinel Ultra Coding Projects (Internal) / Sentinel Task Pull',
      p_metric_kind: 'cumulative',
    });
    continue;
  }

  const metric = byEmail.get(email) || {
    p_email: email,
    p_project_slug: 'sentinel_ultra',
    p_as_of: asOf,
    p_submitted: 0,
    p_accepted: 0,
    p_rejected: 0,
    p_rework: 0,
    p_evaluation_pending: 0,
    p_source_sheet: 'Snorkel MainSentinel Ultra Coding Projects (Internal) / Sentinel Task Pull',
    p_metric_kind: 'cumulative',
  };
  const statusKey = classify(read(row, 'Task Status', 'Status', 'Final Status', 'Task State'));
  metric.p_submitted += 1;
  if (statusKey !== 'submitted') metric['p_' + statusKey] += 1;
  byEmail.set(email, metric);
}

return [...byEmail.values()].map((json) => ({ json }));
